    tierMajor: "大赛", tierHigh: "高级别", tierRegular: "常规赛", tierOther: "其他",
    allTiers: "全部级别",
    podiumSF: "四强", qualList: "资格赛 / 预赛赛果", groupList: "赛果（非单败赛制）",
    eventResults: "赛事成绩", showAll: "展开全部", collapse: "收起", wo: "W/O",
    bronzeMatch: "铜牌赛", finalStage: "决赛阶段", quarter: (i) => `${i}/4区`,
