    attack: "Attack", defence: "Defence", unknown: "?",
    peak: "Peak rating", curRating: "Current rating", curRank: "Current rank",
    sex: "Sex", male: "M", female: "W",
    ratingHistory: "Rating history",
    back: "← Back to rankings",
    loadFail: "Failed to load data",
    notFound: "Player not found",
    notRanked: "—",
    newMark: "NEW",
